L12_1.m_CharStrID = "COMMANDER_NPC_NULL_NULL"
L12_1.m_Talk_KOREA = "공작님! 그게… 고위 흡혈귀로 보이는 자 하나가 영지의 입구를 막고 있습니다."
L12_1.m_fTalkTime = 0.03
