L13_1.m_CharStrID = "BAAUER_NPC_NULL_NULL"
L13_1.m_Talk_KOREA = "고위 흡혈귀라고? 이제 몇 마리 남지도 않은 족속이 스스로 전선까지 기어 나왔단 말인가? 그것도 혼자?"
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "高位の吸血鬼だと？　もう何匹も残っていない輩が、自ら戦線まで出てきやがったのか？　それも1人で？"
L13_1.m_Talk_ENG = "A high-class vampire? Those things are almost extinct, but one has decided to come out of its hole? And alone at that?"
L13_1.m_Talk_TWN = "高階吸血鬼？已經所剩無幾的族群竟然自己爬到前線來了？而且還是一個人？"
L13_1.m_Talk_SCN = "高级吸血鬼？已经所剩无几的族群竟然自己爬到前线来了？而且还是一个人？"
L13_1.m_Talk_DEU = "A high-class vampire? Those things are almost extinct, but one has decided to come out of its hole? And alone at that?"
L13_1.m_Talk_FRA = "A high-class vampire? Those things are almost extinct, but one has decided to come out of its hole? And alone at that?"
