L39_1 = {}
L39_1.m_CutScenKey_Talk = "COUNTERCASE_FALLEN_DOMA_NORMAL_1@39#Talk"
L39_1.m_CutScenProcessKey = 39
L39_1.m_CutScenID = 31721
L39_1.m_CutScenStrID = "COUNTERCASE_FALLEN_DOMA_NORMAL_1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "BAAUER_NPC_NULL_NULL"
L39_1.m_Talk_KOREA = "이, 이럴 수가… 고작 권총 하나로 괴수 무리를 전부 처치하다니 대체 어떻게?"
L39_1.m_fTalkTime = 0.03
L39_1.m_Talk_JPN = "そ、そんな……ピストル1丁で怪獣の群れを全部倒すとは、いったいどうやって？"
L39_1.m_Talk_ENG = "I-I don’t believe it...! He killed all those beasts with just a revolver... How’s that even possible?"
L39_1.m_Talk_TWN = "這，這怎麼可能？！竟然用一把手槍就解決了所有怪物！到底是怎麼做到的？"
L39_1.m_Talk_SCN = "这，这怎么可能？！竟然用一把手枪就解决了所有怪物！到底是怎么做到的？"
L39_1.m_Talk_DEU = "I-I don’t believe it...! He killed all those beasts with just a revolver... How’s that even possible?"
L39_1.m_Talk_FRA = "I-I don’t believe it...! He killed all those beasts with just a revolver... How’s that even possible?"
L40_1 = {}
L40_1.m_CutScenKey_Talk = "COUNTERCASE_FALLEN_DOMA_NORMAL_1@40#Talk"
L40_1.m_CutScenProcessKey = 40
L40_1.m_CutScenID = 31721
L40_1.m_CutScenStrID = "COUNTERCASE_FALLEN_DOMA_NORMAL_1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_Face = "UNIT_LAUGH"
L40_1.m_CharStrID = "DOMA_FALLEN_NULL_NULL"
L40_1.m_Pos = "C"
L40_1.m_Talk_KOREA = "별 말씀을. 그저 가볍게 피하면서 급소만 노렸을 뿐이랍니다."
L40_1.m_fTalkTime = 0.03
L40_1.m_Talk_JPN = "ふふ、朝飯前でしたよ。ただ軽くよけながら急所を狙ったまでですから。"
L40_1.m_Talk_ENG = "Why, thank you. All I did was avoid their attacks and shoot for their weak spots."
L40_1.m_Talk_TWN = "小意思，我只是輕鬆地閃避了幾下，然後瞄準要害開了幾槍而已。"
L40_1.m_Talk_SCN = "说什么呢。我只是轻松地闪避了几下，然后瞄准要害开了几枪而已。"
L40_1.m_Talk_DEU = "Why, thank you. All I did was avoid their attacks and shoot for their weak spots."
L40_1.m_Talk_FRA = "Why, thank you. All I did was avoid their attacks and shoot for their weak spots."
