L42_1.m_CutScenKey_Talk = "COUNTERCASE_FALLEN_DOMA_NORMAL_1@42#Talk"
L42_1.m_CutScenProcessKey = 42
L42_1.m_CutScenID = 31721
L42_1.m_CutScenStrID = "COUNTERCASE_FALLEN_DOMA_NORMAL_1"
L42_1.m_bWaitClick = true
