L42_1.m_BGCrash = 20
L42_1.m_fBGCrashTime = 0.5
L42_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_04"
L42_1.m_CharStrID = "BAAUER_NPC_NULL_NULL"
L42_1.m_Talk_KOREA = "네놈! 감히 날 비웃는 거냐!"
L42_1.m_fTalkTime = 0.03
L42_1.m_Talk_JPN = "貴様！　私をからかっているのか！"
L42_1.m_Talk_ENG = "How dare you mock me!"
L42_1.m_Talk_TWN = "你這傢伙！竟敢嘲諷我！"
L42_1.m_Talk_SCN = "你这家伙！竟敢嘲讽我！"
L42_1.m_Talk_DEU = "How dare you mock me!"
L42_1.m_Talk_FRA = "How dare you mock me!"
L43_1 = {}
L43_1.m_CutScenKey_Talk = "COUNTERCASE_FALLEN_DOMA_NORMAL_1@43#Talk"
L43_1.m_CutScenProcessKey = 43
L43_1.m_CutScenID = 31721
L43_1.m_CutScenStrID = "COUNTERCASE_FALLEN_DOMA_NORMAL_1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "BAAUER_NPC_NULL_NULL"
L43_1.m_Talk_KOREA = "잠깐, 그러고 보니 네 옷의 그 문장은 설마…… 프레데릭 가문?"
L43_1.m_fTalkTime = 0.03
L43_1.m_Talk_JPN = "待て、そういえば貴様の服のその紋章、まさか……フレドレック家？"
L43_1.m_Talk_ENG = "Wait.. That crest on his clothes... Could it be the Frederick family?"
L43_1.m_Talk_TWN = "等一下，仔細一看，你衣服上的那個徽章，難道是…弗雷德里克家族的？"
L43_1.m_Talk_SCN = "等一下，仔细一看，你衣服上的那个徽章，难道是……弗里克家族的？"
L43_1.m_Talk_DEU = "Wait.. That crest on his clothes... Could it be the Frederick family?"
L43_1.m_Talk_FRA = "Wait.. That crest on his clothes... Could it be the Frederick family?"
L44_1 = {}
L44_1.m_CutScenKey_Talk = "COUNTERCASE_FALLEN_DOMA_NORMAL_1@44#Talk"
L44_1.m_CutScenProcessKey = 44
L44_1.m_CutScenID = 31721
L44_1.m_CutScenStrID = "COUNTERCASE_FALLEN_DOMA_NORMAL_1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "BAAUER_NPC_NULL_NULL"
L44_1.m_Talk_KOREA = "<color=#ffd34c>결투자 프레데릭</color>이란 피도 눈물도 없다는 흡혈귀가…… 바로 너였나?!"
L44_1.m_fTalkTime = 0.03
L44_1.m_Talk_JPN = "<color=#ffd34c>決闘者フレドレック</color>という血も涙もない吸血鬼とは……貴様のことだったのか！？"
L44_1.m_Talk_ENG = "So you’re the heartless vampire, <color=#ffd34c>Frederick the Duelist</color>!"
L44_1.m_Talk_TWN = "<color=#ffd34c>決鬥者弗雷德里克</color>那個沒血沒淚的吸血鬼…就是你嗎？！"
L44_1.m_Talk_SCN = "<color=#ffd34c>决斗者弗里克</color>那个冷血无情的吸血鬼……就是你吗？！"
L44_1.m_Talk_DEU = "So you’re the heartless vampire, <color=#ffd34c>Frederick the Duelist</color>!"
L44_1.m_Talk_FRA = "So you’re the heartless vampire, <color=#ffd34c>Frederick the Duelist</color>!"
L45_1 = {}
L45_1.m_CutScenKey_Talk = "COUNTERCASE_FALLEN_DOMA_NORMAL_1@45#Talk"
L45_1.m_CutScenProcessKey = 45
L45_1.m_CutScenID = 31721
L45_1.m_CutScenStrID = "COUNTERCASE_FALLEN_DOMA_NORMAL_1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_IDLE"
L45_1.m_CharStrID = "DOMA_FALLEN_NULL_NULL"
L45_1.m_Pos = "C"
L45_1.m_Talk_KOREA = "이런, 제 하찮은 이름을 바우어 공작께서 알고 계시다니 영광일 따름이군요."
L45_1.m_fTalkTime = 0.03
L45_1.m_Talk_JPN = "おっと、私のくだらない名前をバウアー公爵がご存じだったとは、光栄ですね。"
L45_1.m_Talk_ENG = "Oh my, it’s an honor for a person of your status to recognize a low-life like me, Duke Bower."
L45_1.m_Talk_TWN = "哎呀，能讓鮑爾公爵知道我這微不足道的名字，真是榮幸之至啊。"
L45_1.m_Talk_SCN = "哎呀，能让鲍泽公爵知道我这微不足道的名字，真是荣幸之至啊。"
L45_1.m_Talk_DEU = "Oh my, it’s an honor for a person of your status to recognize a low-life like me, Duke Bower."
L45_1.m_Talk_FRA = "Oh my, it’s an honor for a person of your status to recognize a low-life like me, Duke Bower."
