L47_1.m_CharStrID = "BAAUER_NPC_NULL_NULL"
L47_1.m_Talk_KOREA = "하, 하지만 내 라이칸스로프는 혼자서 성벽을 찢어발기는 괴물이다!"
L47_1.m_fTalkTime = 0.03
L47_1.m_Talk_JPN = "だ、だが私のライカンスロープは1人で城壁を切り裂く化け物だ！"
L47_1.m_Talk_ENG = "B-but my lycanthropes are monsters that can tear down castle walls singlehandedly!"
L47_1.m_Talk_TWN = "但，但我的狼人可是能撕裂城牆的怪物啊！"
L47_1.m_Talk_SCN = "但，但我的狼人可是能撕裂城墙的怪物啊！"
L47_1.m_Talk_DEU = "B-but my lycanthropes are monsters that can tear down castle walls singlehandedly!"
L47_1.m_Talk_FRA = "B-but my lycanthropes are monsters that can tear down castle walls singlehandedly!"
