L3_1 = "조련이란 명목으로 그들의 지성을 망가뜨리고 그저 달려들 줄 밖에 모르는 괴물로 만든 건 당신들이죠. 안 그렇습니까?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "操練という名目で彼らの知性を壊し、ただ飛びかかることしか能のない化け物にしたのはあなたたちでしょう。違いますか？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "But you’re the one who turned them into mindless monsters who only know how to attack, no?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "以馴養之名摧毀他們的智慧，把他們變成只會撲上來的怪物，不是你們幹的嗎？不是嗎？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "以驯养之名摧毁他们的智慧，把他们变成只会扑上来的怪物，不是你们干的吗？不是吗？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "But you’re the one who turned them into mindless monsters who only know how to attack, no?"
L2_1.m_Talk_DEU = L3_1
