L12_1 = "전장에 나오면서 싸울 준비도 되어 있지 않은 이기적이고 연약한 인간이죠."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "戦場に出るというのに戦う準備もできていない、自分勝手で軟弱な人間。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "You’re a foolish and weak human being who shouldn’t be on the battlefield."
L11_1.m_Talk_ENG = L12_1
L12_1 = "是個上了戰場，卻沒有做好戰鬥準備的自私又脆弱的人類。"
