L14_1.m_Face = "UNIT_LAUGH"
L14_1.m_CharStrID = "DOMA_FALLEN_NULL_NULL"
L14_1.m_Pos = "C"
L15_1 = "저 프레데릭 도마. 비록 하찮은 흡혈귀일 뿐이나 난잡한 싸움 보다는 명예로운 일대일의 결투를 선호한답니다."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "私、フレドレック・ドマ。くだらない吸血鬼に過ぎませんが、乱雑な戦いよりは名誉のある一対一の決闘が好みです。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "I, Frederick Doma, may be a lowly vampire... But I prefer an honorable duel rather than this pathetic thing you call a battle."
L14_1.m_Talk_ENG = L15_1
L15_1 = "我，弗雷德里克·多馬。雖然只是個微不足道的吸血鬼，但我更喜歡光明正大的單挑，而不是混戰。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "我，弗里克·多马。虽然只是个卑微的吸血鬼，但我更喜欢光明正大的单挑，而不是乱斗。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "I, Frederick Doma, may be a lowly vampire... But I prefer an honorable duel rather than this pathetic thing you call a battle."
L14_1.m_Talk_DEU = L15_1
L15_1 = "I, Frederick Doma, may be a lowly vampire... But I prefer an honorable duel rather than this pathetic thing you call a battle."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "COUNTERCASE_FALLEN_DOMA_NORMAL_1@65#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 31721
L15_1.m_CutScenStrID = "COUNTERCASE_FALLEN_DOMA_NORMAL_1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_IDLE"
L15_1.m_CharStrID = "DOMA_FALLEN_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "저와 결투를 원한다면 지금이라도 당장 그 허리춤의 총을 쥐어 보이십시오."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "私と決闘したいのなら、今すぐにでもその腰の銃を手に取ってください。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "If you want to duel me, why don’t you grab that pistol of yours on your side?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "如果你想和我決鬥，現在就拔出你腰間的槍。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "如果你想和我决斗，现在就拔出你腰间的枪。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "If you want to duel me, why don’t you grab that pistol of yours on your side?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "If you want to duel me, why don’t you grab that pistol of yours on your side?"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
