L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "DOMA_FALLEN_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "물론 그때가 되면, 손가락 하나로 봐 드리지는 않을 겁니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "もちろんその時は、指一本では済みません。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "But if you do... your finger will be the least of your worries."
L16_1.m_Talk_ENG = L17_1
L17_1 = "當然，到那時，我可不會手下留情。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "当然，到那时，我可不会手下留情。"
