L25_1 = "看來魔王的軍隊也越來越強大了。人類的軍隊竟然能進入我們一族的領地。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "看来魔王的军队也越来越强大了。人类的军队竟然能进入了我们一族的领地。"
