L25_1 = "The Demon Lord’s army must be growing stronger by the second. I can’t believe the human army is already at our doorsteps."
L24_1.m_Talk_DEU = L25_1
L25_1 = "The Demon Lord’s army must be growing stronger by the second. I can’t believe the human army is already at our doorsteps."
