L32_1 = "뭐, 도망치지 않는다고 해도 당신에게 제 귀한 총알을 낭비하는 일은 없겠지만요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "まあ、逃げないとしてもあなたに私の貴重な銃弾を無駄遣いすることはありませんが。"
L31_1.m_Talk_JPN = L32_1
