L38_1 = "살기를 전혀 숨기지 않는 걸 보니 좋은 의도로 찾아오신 건 아니겠지요?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "まったく殺気を隠していないのを見ると、友好的な意図で訪れたわけではないでしょう。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Judging by how you’re glaring at me, I doubt you're here with good intentions."
L37_1.m_Talk_ENG = L38_1
L38_1 = "看你毫不掩飾殺氣，是不懷好意吧？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "看你毫不掩饰杀气，是不怀好意吧？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Judging by how you’re glaring at me, I doubt you're here with good intentions."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Judging by how you’re glaring at me, I doubt you're here with good intentions."
