L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "동족의 피비린내가 진한 걸… 네가 한 짓이야?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "同族の血の匂いがすごいな……あんたがやったのか？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "These lands reek of my people’s blood. Was this your doing?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "同族的血腥味這麼濃…是你幹的嗎？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "同族的血腥味这么浓……是你干的吗？"
