L42_1 = "COUNTERCASE_FALLEN_DOMA_NORMAL_1@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 31721
L41_1.m_CutScenStrID = "COUNTERCASE_FALLEN_DOMA_NORMAL_1"
