L41_1.m_Face = "UNIT_LAUGH"
L41_1.m_CharStrID = "DOMA_FALLEN_NULL_NULL"
L41_1.m_Pos = "C"
L42_1 = "그렇습니다. 제가 이 불쌍한 짐승들에게 총탄을 선사했죠."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "そうです。私がこの可哀想な獣たちに銃弾をプレゼントしたのです。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Yes, it is. I gave those poor beasts a bullet they deserved."
L41_1.m_Talk_ENG = L42_1
L42_1 = "是的，是我送這些可憐的野獸吃子彈的。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "是的，我给这些可怜的野兽送去了子弹。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Yes, it is. I gave those poor beasts a bullet they deserved."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Yes, it is. I gave those poor beasts a bullet they deserved."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "COUNTERCASE_FALLEN_DOMA_NORMAL_1@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 31721
L42_1.m_CutScenStrID = "COUNTERCASE_FALLEN_DOMA_NORMAL_1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_IDLE"
L42_1.m_CharStrID = "DOMA_FALLEN_NULL_NULL"
L42_1.m_Pos = "C"
L43_1 = "그런데 당신은… 그들과 달리 공작에게 길들여진 것 같지 않군요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ところで、あなたは……彼らとは違って公爵に躾けられていないようですね。"
L42_1.m_Talk_JPN = L43_1
