L43_1.m_Talk_JPN = L44_1
L44_1 = "Isn’t it ironic that a half-blood like yourself is stronger than any other pure-blood out there?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "諷刺的是，身為混種的你，卻比任何純種的狼人都要強大。"
