L35_1 = "외모로 사람을 평가하다니 섭섭하군요. 전 당신과 별반 다르지 않은 괴물입니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "見た目で人を評価するとは、悲しいことですね。私はあなたとそう変わらない化け物です。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Shame on you for judging another being by their cover. However, I am a monster just like you."
L34_1.m_Talk_ENG = L35_1
L35_1 = "居然用外貌來評判人，真是讓人傷心啊。我和你沒什麼兩樣，都是怪物。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "居然用外貌来评判人，真是让人伤心啊。我和你没什么两样，都是怪物。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Shame on you for judging another being by their cover. However, I am a monster just like you."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Shame on you for judging another being by their cover. However, I am a monster just like you."
